INSERT INTO public.documento_modelos (id, tipo, nome, conteudo, ativo, ordem, criado_em) VALUES ('79d4f7e9-9777-41ef-bec3-1d981e0e5f04', 'encaminhamento', 'Avaliação Periodontal', 'Encaminho o(a) {{paciente}} solicitando avaliação periodontal e o tratamento que julgar necessário. Agradeço antecipadamente pela atenção dedicada ao paciente.', true, 1, '2026-07-24T01:11:01.903245+00:00');
INSERT INTO public.documento_modelos (id, tipo, nome, conteudo, ativo, ordem, criado_em) VALUES ('679531e2-c6d3-4278-aa8e-362d4cb192b6', 'encaminhamento', 'Exodontia', 'Encaminho o(a) {{paciente}} solicitando avaliação para exodontia do(s) {{dente_singular_plural}}: {{campo_dentes}}. Agradeço antecipadamente pela atenção dedicada ao paciente.', true, 2, '2026-07-24T01:11:01.903245+00:00');
INSERT INTO public.documento_modelos (id, tipo, nome, conteudo, ativo, ordem, criado_em) VALUES ('6faefad1-581b-4b88-994b-ed3cb512515a', 'encaminhamento', 'Endodontia', 'Encaminho o(a) {{paciente}} solicitando avaliação endodôntica do(s) {{dente_singular_plural}}: {{campo_dentes}} e o tratamento que julgar necessário. Agradeço antecipadamente pela atenção dedicada ao paciente.', true, 3, '2026-07-24T01:11:01.903245+00:00');
INSERT INTO public.documento_modelos (id, tipo, nome, conteudo, ativo, ordem, criado_em) VALUES ('c430b06f-67dd-4e52-a88e-af36f44fa262', 'encaminhamento', 'Avaliação Geral', 'Encaminho o(a) {{paciente}} para avaliação geral da saúde bucal. Solicito que seja realizada profilaxia, avaliação da presença de tecido cariado nas arcadas superior e inferior, avaliação periodontal e análise das condições das restaurações. Agradeço antecipadamente pela atenção dedicada ao paciente.', true, 4, '2026-07-24T01:11:01.903245+00:00');
INSERT INTO public.documento_modelos (id, tipo, nome, conteudo, ativo, ordem, criado_em) VALUES ('503b8c45-4ba0-4824-8372-35cf515cc8d9', 'encaminhamento', 'Implante', 'Encaminho o(a) {{paciente}} para avaliação e possível instalação de implantes na região do(s) {{dente_singular_plural}}: {{campo_dentes}}, bem como para planejamento da reabilitação protética. Agradeço antecipadamente pela atenção dedicada ao paciente.', true, 5, '2026-07-24T01:11:01.903245+00:00');
INSERT INTO public.documento_modelos (id, tipo, nome, conteudo, ativo, ordem, criado_em) VALUES ('fbe29964-e378-473a-b3d6-180e3ce5ec5d', 'encaminhamento', 'Ortodontia', 'Encaminho o(a) {{paciente}} para avaliação ortodôntica e planejamento do tratamento que julgar necessário. Agradeço antecipadamente pela atenção dedicada ao paciente.', true, 6, '2026-07-24T01:11:01.903245+00:00');
INSERT INTO public.documento_modelos (id, tipo, nome, conteudo, ativo, ordem, criado_em) VALUES ('dfd48256-3842-4275-b24f-c387d94edde6', 'atestado', 'Atestado Odontológico', 'Regulamentado pelas Leis nº 5.081, de 24/08/1966, e nº 6.215, de 30/06/1975. Atesto, para fins {{finalidade}}, a pedido, que {{paciente}} esteve sob tratamento odontológico neste consultório, no período das {{hora_inicio}} às {{hora_fim}} horas, no dia {{data}}{{repouso}}.', true, 7, '2026-07-24T01:11:01.903245+00:00');
INSERT INTO public.documento_modelos (id, tipo, nome, conteudo, ativo, ordem, criado_em) VALUES ('b6f4e2a4-9893-4e36-bb6b-c1269d040d85', 'declaracao', 'Declaração de Comparecimento', 'Declaro que o(a) paciente {{paciente}} compareceu a esta clínica odontológica no dia {{data}}, no horário das {{hora_inicio}} às {{hora_fim}} horas, para realização de tratamento odontológico.', true, 8, '2026-07-24T01:11:01.903245+00:00');
